lendswift.script:
function isBlank(name) {
  return !name || name.trim() === "" || !/[a-zA-Z]/.test(name);
}

const constants = steps.constants.output;
const allowedStates = constants.states;
const state = payload.personalInformation.state;
const validState = allowedStates.includes(state);

const firstName = steps.parse_name.output.firstName;
const lastName = steps.parse_name.output.lastName;
const validName = !isBlank(firstName) && !isBlank(lastName);

const biddingActive = constants.biddingActive;

const loanAmount = payload.loanInformation.loanAmount;
const validLoanAmount = loanAmount <= constants.maximumLoanAmount;

// Military exclusion (#926). This read payload.personalInformation.militaryStatus
// until 2026-08-21, a field the partner has never sent, so the strict
// comparison against true was always false and the rejection below was
// unreachable: zero rejections in 150,110 runs over 7 days, while 157 leads
// carrying employmentStatus 'military' were sold. The signal the partner does
// send is financialInformation.employmentStatus, one of employed,
// employed_full_time, employed_part_time, military, not_employed, other,
// retired. Measured present on 27,809 of 27,809 leads across both workflows.
const financial = payload.financialInformation || {};
const employmentStatus = financial.employmentStatus;
const knownEmploymentStatus = typeof employmentStatus === 'string' && employmentStatus !== '';
const isMilitary = employmentStatus === 'military';

// All checks pass -> continue to the next node
if (biddingActive && validState && validName && validLoanAmount && knownEmploymentStatus && !isMilitary) {
  return { valid: true };
}

const headers = { "Content-Type": "application/json" };

if (!biddingActive) {
  console.log(`Rejected due to bidding not being active: ${biddingActive}`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadUuid, status: "rejected", reason: "bidding not active" } } };
}

if (!validState) {
  console.log(`Rejected due to invalid_state: ${state}`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadUuid, status: "rejected", reason: "ineligible state" } } };
}

if (!validName) {
  console.log(`Rejected due to invalid name: firstName="${firstName}", lastName="${lastName}"`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadUuid, status: "rejected", reason: "invalid name" } } };
}

if (!validLoanAmount) {
  console.log(`Rejected due to loan amount: ${loanAmount}`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadUuid, status: "rejected", reason: "loan amount exceeds maximum" } } };
}

if (isMilitary) {
  console.log(`Rejected due to military status: employmentStatus=${employmentStatus}`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadUuid, status: "rejected", reason: "military status ineligible" } } };
}

// Fails closed rather than open, which is the whole point of the repair: the
// exclusion above must not be defeated by the field simply being absent. It has
// been present on every lead measured, so this is expected never to fire. If it
// starts firing, the partner payload changed, and it says so rather than
// silently readmitting the population the exclusion exists to keep out.
if (!knownEmploymentStatus) {
  console.log(`Rejected due to missing employment status: ${JSON.stringify(employmentStatus)}`);
  return { response: { status: 200, headers, body: { lead_id: payload.leadUuid, status: "rejected", reason: "employment status missing" } } };
}

